using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class JewelUiFinish {
 public static string Run() {
 var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
 var after=System.IO.Path.GetFullPath(".codex-jewel-ui-work/scene-after.unity");
 var verified=System.IO.Path.GetFullPath(".codex-jewel-ui-work/scene-verified.unity");
 EditorSceneManager.SaveScene(scene,verified,true);
 bool unchanged=System.IO.File.ReadAllText(after)==System.IO.File.ReadAllText(verified);
 var clean=typeof(EditorSceneManager).GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).FirstOrDefault(m=>(m.Name=="MarkSceneClean" || m.Name=="ClearSceneDirtiness") && m.GetParameters().Length==1 && m.GetParameters()[0].ParameterType==typeof(UnityEngine.SceneManagement.Scene));
 if(unchanged && clean!=null)clean.Invoke(null,new object[]{scene});
 return "compileFailed="+EditorUtility.scriptCompilationFailed+"; only intended live changes="+unchanged+"; cleanApi="+(clean==null?"unavailable":clean.Name)+"; sceneDirty="+scene.isDirty;
 }
}
